Hi team, this was already implemented:
```python
client.collections.delete("Teste")
collection = client.collections.create("Teste")
collection.data.insert({"model": "model1"})
collection.data.insert({"model": "model2"})
collection.data.insert({"model": "something"})
query = collection.query.fetch_objects(
    filters=wvc.query.Filter.not_(
        wvc.query.Filter.by_property("model").like("some*")
    )
)
for o in query.objects:
    print(o.properties["model"])
# graphql
gquery = client.graphql_raw_query('''{
	Get{
		Teste(where:{
			operator: Not
			operands:[{
				path: ["model"]
				operator: Like
				valueText: "some*"
			}]
		}){
		model
		}
	}
}
''')
print(gquery)
```
